SET NAMES utf8mb4;
SET TIME_ZONE = '+07:00';
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

CREATE DATABASE IF NOT EXISTS `elo_quiz` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `elo_quiz`;

-- ---------------------------------------------------------------------
-- Bảng: `CAUHINH`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `CAUHINH`;
CREATE TABLE IF NOT EXISTS `CAUHINH` (
  `MaCauHinh` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `TenCauHinh` varchar(60) NOT NULL,
  `GiaTri` varchar(100) NOT NULL,
  `MoTa` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`MaCauHinh`),
  UNIQUE KEY `uq_cauhinh_ten` (`TenCauHinh`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Dữ liệu của bảng `CAUHINH` (20 dòng)
INSERT INTO `CAUHINH` (`MaCauHinh`, `TenCauHinh`, `GiaTri`, `MoTa`) VALUES
  (1, 'SO_CAU', '10', 'Số câu mỗi trận (chụp vào CAUHOITRANDAU lúc tạo trận)'),
  (2, 'THOI_GIAN_MOI_CAU', '15', 'Thời gian trả lời mỗi câu (giây)'),
  (3, 'DIEM_CO_BAN', '100', 'Điểm cơ bản cho câu đúng'),
  (4, 'HE_SO_THUONG', '50', 'Điểm thưởng tối đa theo tốc độ: HE_SO_THUONG x (còn lại / quy định)'),
  (5, 'K_NGUOI_MOI', '32', 'Hệ số K khi người chơi dưới ngưỡng số trận'),
  (6, 'K_NGUOI_CU', '24', 'Hệ số K từ ngưỡng số trận trở lên'),
  (7, 'NGUONG_SO_TRAN_DOI_K', '30', 'Số trận để đổi từ K_NGUOI_MOI sang K_NGUOI_CU'),
  (8, 'ELO_KHOI_TAO', '1000', 'Elo ban đầu của một môn'),
  (9, 'NGUONG_ELO_GHEP_DOI', '100', 'Chênh lệch Elo ban đầu khi ghép; nới dần theo thời gian chờ'),
  (10, 'THOI_GIAN_CHO_GHEP_TOI_DA', '60', 'Quá thời gian này (giây) chưa ghép được thì rút khỏi hàng đợi'),
  (11, 'THOI_GIAN_CHO_VAO_PHONG', '30', 'Sau khi ghép, quá thời gian này (giây) có người chưa vào phòng thì hủy trận'),
  (12, 'THOI_GIAN_CHO_PHEP_MAT_KET_NOI', '30', 'Không có hoạt động quá thời gian này (giây) thì bị xử thua'),
  (13, 'DUNG_SAI_DO_TRE', '1', 'Đáp án đến muộn trong khoảng này (giây) vẫn được nhận'),
  (14, 'SO_TRAN_TOI_THIEU_BXH', '10', 'Số trận tối thiểu của một môn để lên BXH toàn trường'),
  (15, 'THOI_HAN_LIEN_KET_DAT_LAI', '30', 'Hạn của liên kết đặt lại mật khẩu (phút)'),
  (16, 'NGUONG_TRAN_KEO_DAI', '10', 'Trận quá thời gian này (phút) bị liệt kê là bất thường'),
  (17, 'NGUONG_BIEN_DONG_ELO', '150', 'Elo tăng/giảm quá mức này trong khoảng thời gian bên dưới thì cảnh báo'),
  (18, 'KHOANG_BIEN_DONG_ELO', '24', 'Khoảng thời gian xét biến động Elo (giờ)'),
  (19, 'MIN_LUOT_DO_KHO', '1', 'Số lượt trả lời tối thiểu để một câu hỏi được xét độ khó theo dữ liệu thật (Ngân hàng câu hỏi)'),
  (25, 'SCHEMA_VERSION', '8', 'Phiên bản cấu trúc CSDL chuẩn hóa');

-- ---------------------------------------------------------------------
-- Bảng: `LOAIKYTHI`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `LOAIKYTHI`;
CREATE TABLE IF NOT EXISTS `LOAIKYTHI` (
  `MaLoaiKT` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `TenLoaiKT` varchar(50) NOT NULL,
  `MoTa` text DEFAULT NULL,
  PRIMARY KEY (`MaLoaiKT`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Dữ liệu của bảng `LOAIKYTHI` (3 dòng)
INSERT INTO `LOAIKYTHI` (`MaLoaiKT`, `TenLoaiKT`, `MoTa`) VALUES
  (1, 'Giữa kỳ', 'Câu hỏi ôn thi giữa kỳ'),
  (2, 'Cuối kỳ', 'Câu hỏi ôn thi cuối kỳ'),
  (3, 'Cả 2', 'Ôn tập bao gồm cả câu hỏi giữa kỳ và cuối kỳ');

-- ---------------------------------------------------------------------
-- Bảng: `NGUOIDUNG`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `NGUOIDUNG`;
CREATE TABLE IF NOT EXISTS `NGUOIDUNG` (
  `MaND` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `HoTen` varchar(100) NOT NULL,
  `Email` varchar(150) NOT NULL,
  `MatKhau` varchar(255) NOT NULL COMMENT 'Lưu dạng băm (password_hash)',
  `AnhDaiDien` varchar(255) DEFAULT NULL COMMENT 'Đường dẫn file; NULL = ảnh mặc định',
  `Lop` varchar(50) DEFAULT NULL,
  `Khoa` varchar(100) DEFAULT NULL,
  `TrangThai` enum('Hoạt động','Bị khóa') NOT NULL DEFAULT 'Hoạt động',
  `NgayTao` datetime NOT NULL DEFAULT current_timestamp(),
  `NgayDoiMatKhau` datetime DEFAULT NULL,
  `TrangThaiKhaoSat` enum('Chưa làm','Hoàn tất','Bỏ qua') NOT NULL DEFAULT 'Chưa làm',
  `MucTieuKhaoSat` varchar(255) DEFAULT NULL COMMENT 'Danh sách mã mục tiêu, phân tách bằng dấu phẩy',
  `LinhVucYeuThich` varchar(255) DEFAULT NULL COMMENT 'Danh sách mã lĩnh vực yêu thích, phân tách bằng dấu phẩy',
  `TrinhDoTuDanhGia` enum('Mới bắt đầu','Trung bình','Khá','Nâng cao') DEFAULT NULL COMMENT 'Trình độ tự đánh giá khi làm khảo sát',
  `NgayKhaoSat` datetime DEFAULT NULL COMMENT 'Thời điểm bấm Hoàn tất hoặc Bỏ qua khảo sát',
  `TuongChon` varchar(40) NOT NULL DEFAULT 'sunflower',
  `ChoPhepBot` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`MaND`),
  UNIQUE KEY `uq_nguoidung_email` (`Email`)
) ENGINE=InnoDB AUTO_INCREMENT=1000012 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

