-- Bảng: `MONHOC`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `MONHOC`;
CREATE TABLE IF NOT EXISTS `MONHOC` (
  `MaMon` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `TenMon` varchar(150) NOT NULL,
  `MoTa` text DEFAULT NULL,
  `TrangThai` enum('Đang mở','Đã ẩn','Chờ duyệt') NOT NULL DEFAULT 'Đang mở',
  `MaNguoiDeXuat` int(10) unsigned DEFAULT NULL,
  `NgayDeXuat` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`MaMon`),
  KEY `fk_monhoc_nguoidexuat` (`MaNguoiDeXuat`),
  CONSTRAINT `fk_monhoc_nguoidexuat` FOREIGN KEY (`MaNguoiDeXuat`) REFERENCES `NGUOIDUNG` (`MaND`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

