-- ---------------------------------------------------------------------
-- Bảng: `DAPAN`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `DAPAN`;
CREATE TABLE IF NOT EXISTS `DAPAN` (
  `MaDapAn` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaCauHoi` int(10) unsigned NOT NULL,
  `NoiDungDapAn` text NOT NULL,
  `LaDapAnDung` tinyint(1) NOT NULL DEFAULT 0,
  `DapAnDungDuy` int(10) unsigned GENERATED ALWAYS AS (if(`LaDapAnDung` = 1,`MaCauHoi`,NULL)) STORED,
  PRIMARY KEY (`MaDapAn`),
  UNIQUE KEY `uq_dapan_cauhoi_dapan` (`MaCauHoi`,`MaDapAn`),
  UNIQUE KEY `uq_dapan_mot_dung` (`DapAnDungDuy`),
  CONSTRAINT `fk_dapan_cauhoi` FOREIGN KEY (`MaCauHoi`) REFERENCES `CAUHOI` (`MaCauHoi`)
) ENGINE=InnoDB AUTO_INCREMENT=1164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

