-- ---------------------------------------------------------------------
-- Bảng: `HANGDOIGHEPDOI`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `HANGDOIGHEPDOI`;
CREATE TABLE IF NOT EXISTS `HANGDOIGHEPDOI` (
  `MaHangDoi` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaND` int(10) unsigned NOT NULL,
  `MaMon` int(10) unsigned NOT NULL,
  `MaLoaiKT` int(10) unsigned NOT NULL,
  `EloTaiThoiDiemCho` int(11) NOT NULL,
  `ThoiGianVaoHang` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`MaHangDoi`),
  UNIQUE KEY `uq_hangdoi_nd` (`MaND`),
  KEY `idx_hangdoi_ghep` (`MaMon`,`MaLoaiKT`,`EloTaiThoiDiemCho`),
  KEY `fk_hangdoi_loaikt` (`MaLoaiKT`),
  CONSTRAINT `fk_hangdoi_loaikt` FOREIGN KEY (`MaLoaiKT`) REFERENCES `LOAIKYTHI` (`MaLoaiKT`),
  CONSTRAINT `fk_hangdoi_mon` FOREIGN KEY (`MaMon`) REFERENCES `MONHOC` (`MaMon`),
  CONSTRAINT `fk_hangdoi_nd` FOREIGN KEY (`MaND`) REFERENCES `NGUOIDUNG` (`MaND`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------------------------------------------------------------------
-- Bảng: `TRANDAU`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `TRANDAU`;
CREATE TABLE IF NOT EXISTS `TRANDAU` (
  `MaTran` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaMon` int(10) unsigned NOT NULL,
  `MaLoaiKT` int(10) unsigned NOT NULL,
  `ThoiGianTao` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `ThoiGianBatDau` datetime(3) DEFAULT NULL,
  `ThoiGianKetThuc` datetime(3) DEFAULT NULL,
  `TrangThai` enum('Đã ghép','Đang diễn ra','Kết thúc','Hủy') NOT NULL DEFAULT 'Đã ghép',
  `LyDoKetThuc` enum('Hoàn thành','Đối thủ bỏ trận (xử thua)','Hủy do lỗi hệ thống','Hủy do không vào phòng','Quản trị viên hủy','Chịu thua') DEFAULT NULL,
  `DotBien` varchar(30) NOT NULL DEFAULT 'chuan',
  `PhaRoi` text DEFAULT NULL,
  PRIMARY KEY (`MaTran`),
  KEY `idx_trandau_trangthai` (`TrangThai`,`ThoiGianBatDau`),
  KEY `fk_trandau_mon` (`MaMon`),
  KEY `fk_trandau_loaikt` (`MaLoaiKT`),
  CONSTRAINT `fk_trandau_loaikt` FOREIGN KEY (`MaLoaiKT`) REFERENCES `LOAIKYTHI` (`MaLoaiKT`),
  CONSTRAINT `fk_trandau_mon` FOREIGN KEY (`MaMon`) REFERENCES `MONHOC` (`MaMon`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

