-- ---------------------------------------------------------------------
-- Bảng: `NGUOICHOITRANDAU`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `NGUOICHOITRANDAU`;
CREATE TABLE IF NOT EXISTS `NGUOICHOITRANDAU` (
  `MaTran` int(10) unsigned NOT NULL,
  `MaND` int(10) unsigned NOT NULL,
  `DiemSo` int(11) NOT NULL DEFAULT 0,
  `KetQua` enum('Thắng','Thua','Hòa') DEFAULT NULL,
  `EloTruoc` int(11) DEFAULT NULL,
  `EloSau` int(11) DEFAULT NULL,
  `TrangThaiThamGia` enum('Chưa vào','Đang chơi','Đã xong','Bỏ trận') NOT NULL DEFAULT 'Chưa vào',
  `LanHoatDongCuoi` datetime(3) DEFAULT NULL COMMENT 'Cập nhật mỗi lần thiết bị gọi máy chủ (polling)',
  PRIMARY KEY (`MaTran`,`MaND`),
  KEY `idx_nctd_nd_trangthai` (`MaND`,`TrangThaiThamGia`),
  CONSTRAINT `fk_nctd_nd` FOREIGN KEY (`MaND`) REFERENCES `NGUOIDUNG` (`MaND`),
  CONSTRAINT `fk_nctd_tran` FOREIGN KEY (`MaTran`) REFERENCES `TRANDAU` (`MaTran`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

