-- ---------------------------------------------------------------------
-- Bảng: `CAUHOITRANDAU`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `CAUHOITRANDAU`;
CREATE TABLE IF NOT EXISTS `CAUHOITRANDAU` (
  `MaTran` int(10) unsigned NOT NULL,
  `MaCauHoi` int(10) unsigned NOT NULL,
  `ThuTu` tinyint(3) unsigned NOT NULL,
  `DiemCoBan` int(11) NOT NULL,
  `HeSoThuong` int(11) NOT NULL,
  `ThoiGianQuyDinh` int(11) NOT NULL COMMENT 'Giây',
  PRIMARY KEY (`MaTran`,`MaCauHoi`),
  UNIQUE KEY `uq_cauhoitrandau_thutu` (`MaTran`,`ThuTu`),
  KEY `fk_cauhoitrandau_cauhoi` (`MaCauHoi`),
  CONSTRAINT `fk_cauhoitrandau_cauhoi` FOREIGN KEY (`MaCauHoi`) REFERENCES `CAUHOI` (`MaCauHoi`),
  CONSTRAINT `fk_cauhoitrandau_tran` FOREIGN KEY (`MaTran`) REFERENCES `TRANDAU` (`MaTran`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

