-- ---------------------------------------------------------------------
-- Bảng: `ELOMONHOC`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `ELOMONHOC`;
CREATE TABLE IF NOT EXISTS `ELOMONHOC` (
  `MaND` int(10) unsigned NOT NULL,
  `MaMon` int(10) unsigned NOT NULL,
  `DiemElo` int(11) NOT NULL DEFAULT 1000,
  `SoTran` int(10) unsigned NOT NULL DEFAULT 0,
  `SoThang` int(10) unsigned NOT NULL DEFAULT 0,
  `SoThua` int(10) unsigned NOT NULL DEFAULT 0,
  `SoHoa` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`MaND`,`MaMon`),
  KEY `idx_elo_bxh` (`MaMon`,`DiemElo`),
  CONSTRAINT `fk_elo_mon` FOREIGN KEY (`MaMon`) REFERENCES `MONHOC` (`MaMon`),
  CONSTRAINT `fk_elo_nd` FOREIGN KEY (`MaND`) REFERENCES `NGUOIDUNG` (`MaND`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

