-- ---------------------------------------------------------------------
-- Bảng: `CHITIETTRALOI`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `CHITIETTRALOI`;
CREATE TABLE IF NOT EXISTS `CHITIETTRALOI` (
  `MaTran` int(10) unsigned NOT NULL,
  `MaND` int(10) unsigned NOT NULL,
  `MaCauHoi` int(10) unsigned NOT NULL,
  `MaDapAn` int(10) unsigned DEFAULT NULL,
  `ThoiDiemBatDau` datetime(3) DEFAULT NULL COMMENT 'Lúc máy chủ gửi câu cho người chơi; NULL ở dòng tạo bù',
  `ThoiGianTraLoi` decimal(6,3) DEFAULT NULL COMMENT 'Giây đã dùng',
  `DiemNhanDuoc` int(11) NOT NULL DEFAULT 0,
  `TrangThai` enum('Đã trả lời','Hết giờ','Không làm') NOT NULL DEFAULT 'Không làm',
  `ThoiDiemGui` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`MaTran`,`MaND`,`MaCauHoi`),
  KEY `idx_cttl_cauhoi` (`MaCauHoi`),
  KEY `fk_ctl_cauhoitran` (`MaTran`,`MaCauHoi`),
  KEY `fk_ctl_dapan` (`MaCauHoi`,`MaDapAn`),
  CONSTRAINT `fk_ctl_cauhoitran` FOREIGN KEY (`MaTran`, `MaCauHoi`) REFERENCES `CAUHOITRANDAU` (`MaTran`, `MaCauHoi`),
  CONSTRAINT `fk_ctl_dapan` FOREIGN KEY (`MaCauHoi`, `MaDapAn`) REFERENCES `DAPAN` (`MaCauHoi`, `MaDapAn`),
  CONSTRAINT `fk_cttl_nguoichoi` FOREIGN KEY (`MaTran`, `MaND`) REFERENCES `NGUOICHOITRANDAU` (`MaTran`, `MaND`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

