-- ---------------------------------------------------------------------
-- Bảng: `BINHLUAN`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `BINHLUAN`;
CREATE TABLE IF NOT EXISTS `BINHLUAN` (
  `MaBinhLuan` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaBaiDang` int(10) unsigned NOT NULL,
  `MaND` int(10) unsigned NOT NULL,
  `MaBinhLuanCha` int(11) DEFAULT NULL,
  `NoiDung` text NOT NULL,
  `NgayBinhLuan` datetime NOT NULL DEFAULT current_timestamp(),
