-- ---------------------------------------------------------------------
-- Bảng: `THONGBAO`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `THONGBAO`;
CREATE TABLE IF NOT EXISTS `THONGBAO` (
  `MaTB` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaND` int(10) unsigned NOT NULL COMMENT 'Người nhận thông báo',
  `MaNguoiGui` int(10) unsigned NOT NULL COMMENT 'Người thực hiện hành động',
  `MaBaiDang` int(10) unsigned DEFAULT NULL COMMENT 'Bài viết liên quan (NULL với thông báo kết bạn)',
  `MaBinhLuan` int(10) unsigned DEFAULT NULL COMMENT 'Bình luận liên quan nếu có',
  `Loai` varchar(30) NOT NULL DEFAULT 'binhluan' COMMENT 'binhluan, rep_bl, loi_moi_kb, chap_nhan_kb, v.v.',
  `TieuDe` varchar(255) NOT NULL,
  `NoiDung` varchar(500) DEFAULT NULL,
  `LienKet` varchar(255) NOT NULL,
  `DaDoc` tinyint(1) NOT NULL DEFAULT 0,
  `NgayTao` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`MaTB`),
  KEY `idx_thongbao_user` (`MaND`,`DaDoc`,`NgayTao`),
  KEY `idx_thongbao_baidang` (`MaBaiDang`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

