-- ---------------------------------------------------------------------
-- Bảng: `THONGBAO_ADMIN_DADOC`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `THONGBAO_ADMIN_DADOC`;
CREATE TABLE IF NOT EXISTS `THONGBAO_ADMIN_DADOC` (
  `MaAdmin` int(10) unsigned NOT NULL,
  `Loai` tinyint(3) unsigned NOT NULL COMMENT '1 = bài đăng, 2 = bình luận',
  `MaDoiTuong` int(10) unsigned NOT NULL COMMENT 'MaBaiDang hoặc MaBinhLuan',
  `NgayDoc` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`MaAdmin`,`Loai`,`MaDoiTuong`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

