DROP TABLE IF EXISTS `NHATKYQUANTRI`;
CREATE TABLE IF NOT EXISTS `NHATKYQUANTRI` (
  `MaNhatKy` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaAdmin` int(10) unsigned NOT NULL,
  `HanhDong` varchar(100) NOT NULL,
  `DoiTuong` varchar(100) DEFAULT NULL,
  `ThoiGian` datetime NOT NULL DEFAULT current_timestamp(),
  `MoTa` text DEFAULT NULL COMMENT 'Gồm lý do nếu thao tác yêu cầu',
  `DiaChiIP` varchar(45) DEFAULT NULL COMMENT 'IP máy admin khi thao tác (đủ chứa IPv6)',
  `TrangThai` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1 = thành công, 0 = thất bại',
  PRIMARY KEY (`MaNhatKy`),
  KEY `idx_nhatky_admin_tg` (`MaAdmin`,`ThoiGian`),
  KEY `idx_nhatky_tg` (`ThoiGian`),
  KEY `idx_nhatky_trangthai` (`TrangThai`,`ThoiGian`),
  CONSTRAINT `fk_nhatky_admin` FOREIGN KEY (`MaAdmin`) REFERENCES `ADMIN` (`MaAdmin`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

