-- ---------------------------------------------------------------------
-- Bảng: `PHONGTHACHDAU`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `PHONGTHACHDAU`;
CREATE TABLE IF NOT EXISTS `PHONGTHACHDAU` (
  `MaPhong` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaPin` varchar(10) NOT NULL,
  `ChuPhongND` int(10) unsigned NOT NULL,
  `KhachND` int(10) unsigned DEFAULT NULL,
  `MaMon` int(10) unsigned NOT NULL,
  `MaLoaiKT` int(10) unsigned NOT NULL,
  `MaTran` int(10) unsigned DEFAULT NULL,
  `TrangThai` enum('Chờ đối thủ','Đã ghép','Đã hủy') NOT NULL DEFAULT 'Chờ đối thủ',
  `NgayTao` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`MaPhong`),
  UNIQUE KEY `uq_phong_pin` (`MaPin`),
  KEY `idx_phong_chu` (`ChuPhongND`),
  KEY `idx_phong_trangthai` (`TrangThai`,`NgayTao`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

