-- ---------------------------------------------------------------------
-- Bảng: `PHATAFK`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `PHATAFK`;
CREATE TABLE IF NOT EXISTS `PHATAFK` (
  `MaPhat` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `MaND` int(10) unsigned NOT NULL,
  `LyDo` varchar(255) NOT NULL,
  `SoGiay` int(10) unsigned NOT NULL,
  `NgayTao` datetime NOT NULL DEFAULT current_timestamp(),
  `HetHan` datetime NOT NULL,
  `DaGo` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`MaPhat`),
